import React from 'react';

export default function OddsList({ offers = [], disabled }) {
  return (
    <div>
      <h3>Today's Picks</h3>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
        {offers.map(o => (
          <div key={o.id} className="card" style={{ filter: disabled ? 'blur(4px) grayscale(50%)' : 'none', opacity: disabled ? 0.7 : 1 }}>
            <div style={{ fontWeight: 700 }}>{o.matchName}</div>
            <div>Odds: {o.odds || '—'}</div>
            <div>Price: {o.price}</div>
            <div>Expiry: {new Date(o.expiryDate).toLocaleString()}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
